1	import { homedir } from "node:os";
2	import { join } from "node:path";
3	import type { SyncProvider } from "@shared/types/workspaces";
4	import { detectSync, syncProviderOfPath, withTimeout } from "./synced-folder";
5	
6	/**
7	 * What this Mac knows about each registered workspace's provider (spec, Synced folders: "the
8	 * kind is stored on the entry and re-detected on every launch"). Detected at launch, when a
9	 * workspace is added or relocated; until then the path rule answers, which needs no I/O.
10	 */
11	export class SyncStates {
12	  private readonly known = new Map<string, { path: string; sync: SyncProvider | null }>();
13	
14	  constructor(
15	    private readonly detect: (path: string) => Promise<SyncProvider | null> = detectSync,
16	    private readonly home: string = homedir(),
17	  ) {}
18	
19	  async refresh(entry: { id: string; path: string }): Promise<SyncProvider | null> {
20	    const sync = await this.detect(entry.path);
21	    this.known.set(entry.id, { path: entry.path, sync });
22	    return sync;
23	  }
24	
25	  /** The provider of a workspace; a path that changed since the last detection uses the path rule. */
26	  of(entry: { id: string; path: string }): SyncProvider | null {
27	    const hit = this.known.get(entry.id);
28	    if (hit && hit.path === entry.path) return hit.sync;
29	    return syncProviderOfPath(entry.path, this.home);
30	  }
31	}
32	
33	/** `userData/workspace-scratch/<workspaceId>`: a synced workspace's working files, outside it. */
34	export function scratchRoot(userData: string, workspaceId: string): string {
35	  return join(userData, "workspace-scratch", workspaceId);
36	}
37	
38	/** Recording and move staging of a synced workspace (instead of `.kaipu/tmp/`). */
39	export function scratchTmp(userData: string, workspaceId: string): string {
40	  return join(scratchRoot(userData, workspaceId), "tmp");
41	}
